create table invoice_test_results(name text primary key,result jsonb);
grant all on invoice_test_results to authenticated;
create function pg_temp.expect_error(command text,fragment text) returns void language plpgsql as $$begin
 begin execute command;exception when others then if position(fragment in sqlerrm)=0 then raise exception 'Wrong error: % wanted %',sqlerrm,fragment;end if;return;end;
 raise exception 'Expected rejection: %',fragment;
end$$;
create function pg_temp.direct_payload(p_price numeric default 111,p_replace uuid default null) returns jsonb language sql as $$
 select jsonb_build_object('supplier_id','ee300000-0000-4000-8000-000000000001','warehouse_id','ee200000-0000-4000-8000-000000000001','tanggal',current_date,'jatuh_tempo',current_date+30,'no_faktur_pemasok','SUP-FIC','surat_jalan','SJ-FIC','keterangan','Fiction invoice','lampiran','[]'::jsonb,'replaces_invoice_id',p_replace,'items',jsonb_build_array(jsonb_build_object('item_id','ee400000-0000-4000-8000-000000000001','qty',1,'harga',p_price,'satuan','box','exp_date',current_date+365)))
$$;
insert into invoice_test_results values('direct-payload',pg_temp.direct_payload());
create function pg_temp.po_invoice(p_key text,p_qty numeric default .5,p_price numeric default 133.2,p_replace uuid default null) returns jsonb language sql as $$
 select to_jsonb(x) from create_purchase_invoice_from_po('ee500000-0000-4000-8000-000000000001','FB.INV.',5,null,current_date,current_date+30,null,jsonb_build_array(jsonb_build_object('po_item_id','ee600000-0000-4000-8000-000000000001','qty',p_qty,'harga',p_price)),'[]','[]',p_qty*p_price-round(p_qty*p_price/1.11),p_key,p_replace)x
$$;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','ee000000-0000-4000-8000-000000000001',true);
select receive_purchase_order('ee500000-0000-4000-8000-000000000001','invoice-receipt','TB.INV.',5,current_date,null,null,jsonb_build_array(jsonb_build_object('id','ee600000-0000-4000-8000-000000000001','qty_terima',4,'qty_rusak',0,'batches',jsonb_build_array(jsonb_build_object('qty',1,'exp_date',current_date+365),jsonb_build_object('qty',3,'exp_date',current_date+730)))));
reset role;
insert into invoice_test_results select 'before-layers',jsonb_agg(to_jsonb(l) order by id) from stock_layers l;
create function invoice_test_fault() returns trigger language plpgsql as $$begin if current_setting('invoice.test_fault',true)=TG_ARGV[0] then raise exception 'INVOICE_FINAL_FAULT';end if;return new;end$$;
create trigger invoice_test_post_fault before insert on purchase_operations for each row execute function invoice_test_fault('create');
create trigger invoice_test_cancel_fault before insert on purchase_invoice_cancellation_requests for each row execute function invoice_test_fault('cancel');
set local role authenticated;
do $$declare first jsonb;retry jsonb;v uuid;payload jsonb;begin
 perform set_config('invoice.test_fault','create',true);
 perform pg_temp.expect_error('select pg_temp.po_invoice(''fault-po'')','INVOICE_FINAL_FAULT');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''fault-direct'',pg_temp.direct_payload())','INVOICE_FINAL_FAULT');
 if exists(select 1 from purchase_invoices) or (select count(*) from stock_layers)<>2 or (select qty from stock where item_id='ee400000-0000-4000-8000-000000000001')<>40 then raise exception 'Mid-write failure leaked invoice, stock or layer';end if;
 perform set_config('invoice.test_fault','',true);
 first:=pg_temp.po_invoice('po-first');v:=(first->>'invoice_id')::uuid;
 retry:=pg_temp.po_invoice('po-first');
 if first<>retry then raise exception 'Exact PO retry duplicated';end if;
 if get_purchase_operation_result('invoice','po-first')<>first then raise exception 'Lost PO response recovery failed';end if;
 perform pg_temp.expect_error('select pg_temp.po_invoice(''po-first'',.5,144.3)','berbeda');
 if (select sum(qty_left*unit_cost) from stock_layers)<>410 or (select qty from stock where item_id='ee400000-0000-4000-8000-000000000001')<>40 then raise exception 'PO partial repricing value mismatch';end if;
 if not exists(select 1 from stock_layers where qty_left=5 and unit_cost=12) then raise exception 'PO split absent';end if;
 if not exists(select 1 from purchase_invoice_items where invoice_id=v and qty=.5 and faktor=10 and harga=133.2) then raise exception 'PO selected unit lost';end if;
 insert into invoice_test_results values('po-first',first);
 perform pg_temp.expect_error(format('update purchase_invoices set total=0 where id=%L',v),'permission denied');
 perform pg_temp.expect_error(format('delete from purchase_invoice_items where invoice_id=%L',v),'permission denied');
 perform pg_temp.expect_error(format('update journal_entries set deskripsi=''tamper'' where source_ref=%L',first->>'no_faktur'),'dilindungi');
 first:=create_direct_purchase_invoice('direct-first',pg_temp.direct_payload());
 if create_direct_purchase_invoice('direct-first',pg_temp.direct_payload())<>first or get_purchase_operation_result('invoice-direct','direct-first')<>first then raise exception 'Direct retry/recovery failed';end if;
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''direct-first'',pg_temp.direct_payload(222))','berbeda');
 insert into invoice_test_results values('direct-first',first);
 perform pg_temp.expect_error(format('update stock_moves set qty=0 where source_ref=%L',first->>'no_faktur'),'dilindungi');
 if (select qty from stock where item_id='ee400000-0000-4000-8000-000000000001')<>50 then raise exception 'Direct units failed';end if;
 if not exists(select 1 from stock_layers where source_ref=first->>'no_faktur' and qty_left=10 and unit_cost=10) then raise exception 'Direct DPP factor failed';end if;
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''bad-day'',pg_temp.direct_payload()||jsonb_build_object(''tanggal'',''infinity''))','Tanggal');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''future'',pg_temp.direct_payload()||jsonb_build_object(''tanggal'',current_date+1))','Tanggal');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''bad-money'',pg_temp.direct_payload(''NaN''::numeric))','harga');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''bad-unit'',jsonb_set(pg_temp.direct_payload(),''{items,0,satuan}'',''"fake"''))','Satuan');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''bad-expiry'',jsonb_set(pg_temp.direct_payload(),''{items,0,exp_date}'',''"infinity"''))','kedaluwarsa');
 perform pg_temp.expect_error('select create_direct_purchase_invoice(''service'',jsonb_set(pg_temp.direct_payload(),''{items,0,item_id}'',''"ee400000-0000-4000-8000-000000000002"''))','Satuan');
end$$;
reset role;
insert into invoice_test_results select 'source-journals',jsonb_agg(to_jsonb(j) order by id) from journal_entries j;
