set local role authenticated;
do $$declare v uuid;r jsonb;pay jsonb;ord jsonb;begin
 select (result->>'invoice_id')::uuid into v from invoice_test_results where name='direct-first';
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''future-cancel'',''Wrong price'',current_date+1)',v),'Tanggal');
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''invalid-cancel'',''Wrong price'',''infinity''::date)',v),'Tanggal');
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''early-cancel'',''Wrong price'',current_date-1)',v),'mendahului');
 pay:=pay_purchase_invoice_atomic('invoice-payment',v,current_date,50,'Transfer',null,'ee700000-0000-4000-8000-000000000001',null);
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''with-pay'',''Wrong price'')',v),'pembayaran');
 perform cancel_purchase_payment((pay->>'payment_id')::uuid,0,'reverse-invoice-payment','Wrong price');
 ord:=mutate_purchase_payment_order('reserve-invoice','create',null,null,jsonb_build_object('supplier_id','ee300000-0000-4000-8000-000000000001'),jsonb_build_array(jsonb_build_object('invoice_id',v,'jumlah',50)));
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''reserved'',''Wrong price'')',v),'perintah bayar');
 perform mutate_purchase_payment_order('unreserve-invoice','cancel',(ord->>'order_id')::uuid,0,'{}','[]');
 perform set_config('invoice.test_fault','cancel',true);
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''cancel-fault'',''Wrong price'')',v),'INVOICE_FINAL_FAULT');
 if exists(select 1 from purchase_invoices where id=v and voided_at is not null) or (select qty from stock where item_id='ee400000-0000-4000-8000-000000000001')<>50 then raise exception 'Cancellation fault leaked stock or status';end if;
 perform set_config('invoice.test_fault','',true);
 r:=cancel_purchase_invoice(v,0,'cancel-direct','Wrong price');
 if r<>cancel_purchase_invoice(v,0,'cancel-direct','Wrong price') or r<>get_purchase_invoice_cancellation(v,'cancel-direct') then raise exception 'Cancellation retry/recovery failed';end if;
 perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''cancel-direct'',''Changed reason'')',v),'berbeda');
 if (select qty from stock where item_id='ee400000-0000-4000-8000-000000000001')<>40 then raise exception 'Direct cancellation failed stock';end if;
 perform pg_temp.expect_error(format('select pay_purchase_invoice_atomic(''pay-void'',%L,current_date,1,''Transfer'',null,''ee700000-0000-4000-8000-000000000001'',null)',v),'dibatalkan');
 r:=create_direct_purchase_invoice('direct-replacement',pg_temp.direct_payload(222,v));
 if create_direct_purchase_invoice('direct-replacement',pg_temp.direct_payload(222,v))<>r then raise exception 'Replacement retry failed';end if;
 perform pg_temp.expect_error(format('select create_direct_purchase_invoice(''direct-replacement-again'',pg_temp.direct_payload(222,%L))',v),'pengganti sudah tersimpan');
 insert into invoice_test_results values('direct-replacement',r);
 -- A different SKU movement is irrelevant, but this invoice's consumed stock must block.
 select (result->>'invoice_id')::uuid into v from invoice_test_results where name='po-first';
 begin
  perform post_unit_return('purchase','ee500000-0000-4000-8000-000000000001','invoice-return',jsonb_build_object('tanggal',current_date),'[{"item_id":"ee400000-0000-4000-8000-000000000001","source_line_id":"ee600000-0000-4000-8000-000000000001","qty":0.1,"satuan":"box"}]');
  perform pg_temp.expect_error(format('select cancel_purchase_invoice(%L,0,''with-return'',''Wrong price'')',v),'retur');
  raise exception using errcode='ZX001',message='rollback dependent return test';
 exception when sqlstate 'ZX001' then null;end;
 r:=cancel_purchase_invoice(v,0,'cancel-po','Wrong price');
 if (select sum(qty_left*unit_cost) from stock_layers where source='purchase')<>400 then raise exception 'PO cancellation did not restore exact receipt valuation';end if;
 r:=pg_temp.po_invoice('po-replacement',4,133.2,v);
 if (select sum(qty*faktor) from purchase_invoice_items ii join purchase_invoices i on i.id=ii.invoice_id where i.po_id='ee500000-0000-4000-8000-000000000001' and i.voided_at is null)<>40 then raise exception 'Void did not reopen all PO quantity';end if;
 insert into invoice_test_results values('po-replacement',r);
 perform pg_temp.expect_error(format('select pg_temp.po_invoice(''replacement-again'',.5,133.2,%L)',v),'pengganti sudah tersimpan');
end$$;
reset role;
do $$begin
 if (select jsonb_agg(to_jsonb(j) order by id) from journal_entries j where id in(select (x->>'id')::uuid from invoice_test_results,jsonb_array_elements(result)x where name='source-journals')) is distinct from (select result from invoice_test_results where name='source-journals') then raise exception 'Original journals mutated';end if;
 if (select jsonb_agg(to_jsonb(j) order by id) from journal_lines j where id in(select (x->>'id')::uuid from invoice_test_results,jsonb_array_elements(result)x where name='source-lines')) is distinct from (select result from invoice_test_results where name='source-lines') then raise exception 'Original journal lines mutated';end if;
 if (select jsonb_agg(to_jsonb(j) order by id) from purchase_invoice_items j where id in(select (x->>'id')::uuid from invoice_test_results,jsonb_array_elements(result)x where name='source-items')) is distinct from (select result from invoice_test_results where name='source-items') then raise exception 'Original invoice items mutated';end if;
 if exists(select 1 from purchase_invoice_postings p where (select sum(l.debit-l.credit) from journal_lines l where l.entry_id in(p.journal_id,(select reversal_journal_id from purchase_invoices where id=p.invoice_id)))<>0) then raise exception 'Unbalanced source/reversal journals';end if;
end$$;
